package com.bank.fragile.bad;

import com.bank.fragile.model.Transaction;
import java.util.ArrayList;
import java.util.Collections;

public class LeakyTransactionQueue extends ArrayList<Transaction> {

    public void enqueue(Transaction txn) {
        add(txn);
        Collections.sort(this);  // maintain priority order
    }

    public Transaction dequeue() {
        if (isEmpty()) throw new java.util.NoSuchElementException("Queue empty!");
        return remove(0);  // highest priority (lowest number) at front
    }

    // PROBLEM: ALL ArrayList methods are inherited and PUBLIC!
    // Callers can call:
    // - add(0, lowPriorityTxn)  → bypass priority! Insert at front!
    // - remove(0)               → remove highest priority without dequeue!
    // - get(index)              → random access!
    // - set(index, txn)         → replace at arbitrary position!
    // - clear()                 → wipe the queue!
    // The priority contract is BROKEN by inherited methods.
}
