// ─── File: src/main/java/com/bank/fragile/good/SafeTransactionQueue.java ───
// ✅ COMPOSITION: private list, controlled API — LIFO/priority enforced!
package com.bank.fragile.good;

import com.bank.fragile.model.Transaction;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.NoSuchElementException;

public class SafeTransactionQueue {
    private final List<Transaction> queue = new ArrayList<>();  // PRIVATE!

    public void enqueue(Transaction txn) {
        queue.add(txn);
        Collections.sort(queue);  // maintain priority order
    }

    public Transaction dequeue() {
        if (queue.isEmpty()) throw new NoSuchElementException("Queue empty!");
        return queue.remove(0);  // highest priority
    }

    public Transaction peek() {
        if (queue.isEmpty()) throw new NoSuchElementException("Queue empty!");
        return queue.get(0);
    }

    public int size() { return queue.size(); }
    public boolean isEmpty() { return queue.isEmpty(); }

    // THAT'S IT! No add(index), no remove(index), no get(index), no set()!
    // Priority contract ENFORCED — callers can only enqueue/dequeue/peek.
}
```

