// ─── File: src/test/java/com/bank/fragile/FragileBaseClassTest.java ───
package com.bank.fragile;

import com.bank.fragile.bad.LeakyTransactionQueue;
import com.bank.fragile.good.SafeTransactionQueue;
import com.bank.fragile.model.Transaction;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class FragileBaseClassTest {

    Transaction rtgs = new Transaction("RTGS-001", "RTGS", new BigDecimal("50000000"), 1);   // HIGHEST
    Transaction neft = new Transaction("NEFT-001", "NEFT", new BigDecimal("500000"), 2);      // HIGH
    Transaction upi  = new Transaction("UPI-001",  "UPI",  new BigDecimal("100"), 3);          // NORMAL

    // ═══ LEAKY QUEUE: inherited methods BREAK priority ═══
    @Test
    void leaky_priorityBrokenByInheritedAdd() {
        LeakyTransactionQueue queue = new LeakyTransactionQueue();
        queue.enqueue(rtgs);   // priority 1 — should be first
        queue.enqueue(neft);   // priority 2
        queue.enqueue(upi);    // priority 3

        // ❌ BYPASS PRIORITY: insert UPI at front using inherited add(0, ...)!
        Transaction lowPriority = new Transaction("UPI-HACK", "UPI", new BigDecimal("50"), 99);
        queue.add(0, lowPriority);  // ArrayList.add(index, element) — LEAKED!

        Transaction first = queue.dequeue();
        assertThat(first.txnId()).isEqualTo("UPI-HACK");  // WRONG! Should be RTGS!
        // Rs.50 crore RTGS delayed behind Rs.50 UPI — PRIORITY CONTRACT BROKEN!
    }

    @Test
    void leaky_randomAccessBreaksEncapsulation() {
        LeakyTransactionQueue queue = new LeakyTransactionQueue();
        queue.enqueue(rtgs);
        queue.enqueue(upi);

        // ❌ Random access via inherited get():
        Transaction random = queue.get(1);  // ArrayList.get(index) — LEAKED!
        assertThat(random).isNotNull();
        // Queue should only allow dequeue from front — but get(index) allows peeking anywhere!
    }

    // ═══ SAFE QUEUE: composition enforces priority ═══
    @Test
    void safe_priorityMaintained() {
        SafeTransactionQueue queue = new SafeTransactionQueue();
        queue.enqueue(upi);    // priority 3
        queue.enqueue(rtgs);   // priority 1
        queue.enqueue(neft);   // priority 2

        // Dequeue returns highest priority (lowest number) first:
        assertThat(queue.dequeue().txnId()).isEqualTo("RTGS-001");  // priority 1 ✅
        assertThat(queue.dequeue().txnId()).isEqualTo("NEFT-001");  // priority 2 ✅
        assertThat(queue.dequeue().txnId()).isEqualTo("UPI-001");   // priority 3 ✅
    }

    @Test
    void safe_cannotBypassPriority() {
        SafeTransactionQueue queue = new SafeTransactionQueue();
        queue.enqueue(rtgs);

        // queue.add(0, lowPriority);  → COMPILE ERROR! No add(int, Transaction) method!
        // queue.get(0);               → COMPILE ERROR! No get(int) method!
        // queue.remove(0);            → COMPILE ERROR! No remove(int) method!
        // The leaked methods DON'T EXIST on SafeTransactionQueue!
        // Composition HIDES ArrayList's dangerous methods. ✅

        assertThat(queue.dequeue().txnId()).isEqualTo("RTGS-001");  // priority enforced!
    }

    @Test
    void safe_emptyQueueThrowsOnDequeue() {
        SafeTransactionQueue queue = new SafeTransactionQueue();
        assertThatThrownBy(queue::dequeue)
            .isInstanceOf(java.util.NoSuchElementException.class);
    }
}
